VAR Target_Nasional =
    CALCULATE(
        [SPK_Target],
        KEEPFILTERS(MasterArea[Area Code] <> "BALI")
    )
VAR TargetPerDay_Bali =  DIVIDE(Target_Bali, [WorkingDay_Bali])
VAR TargetPerDay_Nasional = DIVIDE(Target_Nasional, [WorkingDay_Nasional])
VAR ConvTargetPerDay_Bali = DIVIDE(0.05, [WorkingDay_Bali])
VAR ConvTargetPerDay_Nasional = DIVIDE(0.05, [WorkingDay_Nasional])

RETURN
SWITCH(
    StageID,
    4, TargetPerDay_Bali + TargetPerDay_Nasional,
    6,  ConvTargetPerDay_Bali + ConvTargetPerDay_Nasional
)
